package gg.rsmod.plugins.content.skills.summoning

import gg.rsmod.game.fs.def.AnimDef
import gg.rsmod.game.model.attr.AttributeKey
import gg.rsmod.game.model.entity.Npc
import gg.rsmod.game.model.entity.Player
import gg.rsmod.plugins.api.cfg.Sfx
import gg.rsmod.plugins.api.ext.message
import gg.rsmod.plugins.api.ext.playSound
import java.io.File

/**
 * The OSRS pet emotes (OSRS Wiki pet pages, section "Emotes"): Butch, Wisp, Yami, Gull, Gulliver ("Emote") and Beef ("Interact").
 *
 * Data: `data/cfg/pets/pet_emotes.tsv` (generated by `OsrsPetImportTool table`; the source list with its evidence is
 * `OsrsPetImportTool.EMOTES`). Rules:
 * - The emotes play "in the following order" (wiki): one per click, then back to the first.
 * - "There is a short cooldown of several seconds between emotes": "You must wait a moment before your pet can do another emote."
 *   OSRS publishes no number; here the pet is busy until its emote ends, and at least [MIN_COOLDOWN] ticks (CUSTOM_SERVER_OVERRIDE).
 * - Yami's standing emote "loops until the player moves or interacts with him".
 * - Beef: Interact -> "Moo." (overhead "moo", Transcript:Beef; sound pet_cow 1170, ADAPTED: OSRS names no sound) or Emote: the sniff,
 *   with "a rare chance" of the whirlwind instead (OSRS gives no rate: 1 in [WHIRLWIND_ONE_IN], CUSTOM_SERVER_OVERRIDE).
 * - The death emotes of Butch and Wisp unlock on OSRS after an awakened kill; the awakened bosses do not exist here, so they are in the
 *   cycle from the start (CUSTOM_SERVER_OVERRIDE).
 */
object PetEmotes {
    const val TABLE_PATH = "./data/cfg/pets/pet_emotes.tsv"
    const val MSG_WAIT = "You must wait a moment before your pet can do another emote."
    const val MIN_COOLDOWN = 5
    const val WHIRLWIND_ONE_IN = 50
    const val RARE = "whirlwind"
    const val LOOPING = "stand"

    /** Most loops of a looping emote (safety net; the owner moving ends it first). */
    const val MAX_LOOPS = 100

    data class Emote(val name: String, val seqs: List<Int>, val spot: Int)

    @Volatile
    var byNpc: Map<Int, List<Emote>> = emptyMap()
        private set

    /** [npc id, next emote index] of the player's pet. */
    private val NEXT_ATTR = AttributeKey<IntArray>()

    /** World cycle until which the pet is busy with an emote. */
    private val BUSY_ATTR = AttributeKey<Int>()

    /** Bumped by every emote: a looping emote stops once a newer one (or none) owns the pet. */
    private val TOKEN_ATTR = AttributeKey<Int>()

    fun parse(lines: List<String>): Map<Int, List<Emote>> =
        lines.filter { it.isNotBlank() && !it.startsWith("#") }.map { line ->
            val c = line.split('\t')
            require(c.size >= 4) { "bad pet emote line '$line'" }
            c[0].trim().toInt() to Emote(c[1].trim(), c[2].split(',').map { it.trim().toInt() }, c[3].trim().toInt())
        }.groupBy({ it.first }, { it.second })

    fun load(file: File = File(TABLE_PATH)): Int {
        if (!file.exists()) return 0
        byNpc = parse(file.readLines())
        return byNpc.values.sumOf { it.size }
    }

    fun hasEmotes(npc: Int): Boolean = Pets.baseNpc(npc) in byNpc

    /** The emotes clicked through in order (Beef's rare whirlwind is not one of them). */
    fun cycle(npc: Int): List<Emote> = byNpc[Pets.baseNpc(npc)].orEmpty().filter { it.name != RARE }

    private fun ownerCheck(
        player: Player,
        npc: Npc,
    ): Boolean {
        if (Pets.current(player) !== npc) {
            player.message("This isn't your pet.")
            return false
        }
        if ((player.attr[BUSY_ATTR] ?: 0) > player.world.currentCycle) {
            player.message(MSG_WAIT)
            return false
        }
        return true
    }

    /** "Emote" on a pet: its next emote in the OSRS order. */
    fun emote(
        player: Player,
        npc: Npc,
    ) {
        if (!ownerCheck(player, npc)) return
        val list = cycle(npc.id)
        if (list.isEmpty()) return
        val next = player.attr[NEXT_ATTR]?.takeIf { it[0] == npc.id }?.get(1) ?: 0
        val emote = list[next % list.size]
        player.attr[NEXT_ATTR] = intArrayOf(npc.id, (next + 1) % list.size)
        play(player, npc, emote)
    }

    /** Beef's Interact -> Emote: the sniff, rarely the whirlwind. */
    fun beefEmote(
        player: Player,
        npc: Npc,
    ) {
        if (!ownerCheck(player, npc)) return
        val all = byNpc[Pets.baseNpc(npc.id)].orEmpty()
        val rare = all.firstOrNull { it.name == RARE }
        val emote = if (rare != null && player.world.random(WHIRLWIND_ONE_IN - 1) == 0) rare else all.firstOrNull { it.name != RARE } ?: return
        play(player, npc, emote)
    }

    /** Beef's Interact -> "Moo.". */
    fun moo(
        player: Player,
        npc: Npc,
    ) {
        if (Pets.current(player) !== npc) {
            player.message("This isn't your pet.")
            return
        }
        npc.forceChat("moo")
        player.playSound(Sfx.PET_COW)
    }

    private fun lengthOf(
        player: Player,
        seq: Int,
    ): Int = player.world.definitions.getNullable(AnimDef::class.java, seq)?.cycleLength?.coerceAtLeast(1) ?: 1

    private fun play(
        player: Player,
        npc: Npc,
        emote: Emote,
    ) {
        val total = emote.seqs.sumOf { lengthOf(player, it) }
        player.attr[BUSY_ATTR] = player.world.currentCycle + maxOf(total, MIN_COOLDOWN)
        gg.rsmod.game.model.Trace.log(gg.rsmod.game.model.Trace.Cat.SUMMON) { "pet emote ${emote.name} seqs=${emote.seqs} npc ${npc.id} for ${player.username}" }
        val start = player.tile
        val token = (player.attr[TOKEN_ATTR] ?: 0) + 1
        player.attr[TOKEN_ATTR] = token
        npc.queue {
            var loops = 0
            do {
                emote.seqs.forEachIndexed { i, seq ->
                    if (Pets.current(player) !== npc || player.attr[TOKEN_ATTR] != token) return@queue
                    npc.animate(seq)
                    if (i == 0 && emote.spot >= 0 && loops == 0) npc.graphic(emote.spot)
                    wait(lengthOf(player, seq))
                }
                loops++
                val keepLooping =
                    emote.name == LOOPING && player.tile == start && Pets.current(player) === npc && player.attr[TOKEN_ATTR] == token &&
                        loops < MAX_LOOPS
            } while (keepLooping)
        }
    }
}
